package vn.covie.notifications.api; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.responses.ApiResponse; import java.util.UUID; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import vn.covie.notifications.api.dto.NotificationPageResponse; import vn.covie.notifications.application.NotificationReadService;
@RestController @RequestMapping("/api/v1/me/notifications") public class MeNotificationController {private final NotificationReadService notifications; public MeNotificationController(NotificationReadService n){notifications=n;} @GetMapping public ResponseEntity<NotificationPageResponse> inbox(@RequestParam(required=false) Integer limit,@RequestParam(required=false) String cursor){return ResponseEntity.ok().cacheControl(CacheControl.noStore().cachePrivate()).body(notifications.inbox(limit,cursor));} @PostMapping("/{notificationId}/mark-read") @Operation(responses=@ApiResponse(responseCode="204",description="No Content")) public ResponseEntity<Void> markRead(@PathVariable UUID notificationId){notifications.markRead(notificationId);return noContent();} @PostMapping("/mark-all-read") @Operation(responses=@ApiResponse(responseCode="204",description="No Content")) public ResponseEntity<Void> markAll(){notifications.markAllRead();return noContent();} private static ResponseEntity<Void> noContent(){return ResponseEntity.noContent().cacheControl(CacheControl.noStore().cachePrivate()).build();}}
